    /**
     * Method to retrieve the Matter via MatterFetchOneSummary
     * @param 	summary MatterFetchOneSummary 
     * @return 	MatterFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Matter getMatter( MatterFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "MatterFetchOneSummary arg cannot be null" );
    	
    	Matter entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Matter
        	// --------------------------------------
        	CompletableFuture<Matter> futureEntity = queryGateway.query(new FindMatterQuery( new LoadMatterFilter( summary.getMatterId() ) ), ResponseTypes.instanceOf(Matter.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Matter with id " + summary.getMatterId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


